private TreeNode<T> rotateRight(TreeNode<T> node) {

    if (node == null) {
        // Empty tree, null cannot be rotated.
        return null;
    } else if (node.left == null) {
        // Already in right position, no need to rotate.
        return node;
    } else {
        // Perform the rotation.
        TreeNode<T> leftChild = node.left;
        TreeNode<T> leftGrandchild = leftChild.right;
        TreeNode<T> rightChild = leftGrandchild.left;

        leftChild.right = leftGrandchild.left;
        node.left = leftGrandchild;
        leftChild.left = node;
        leftGrandchild.left = rightChild;

        // Update the heights of the children and grandchild.
        if (leftChild.height > node.height) {
            node.height = leftChild.height;
        }
        if (leftGrandchild.height > node.height) {
            node.height = leftGrandchild.height;
        }

        return leftGrandchild;
