  for (V vertex : target.getVertices()) {
    resultMap.put(vertex.getId(), vertex);
  }

  // Step 2: Randomly generate edges for the bipartite graph
  for (V vertex : target.getVertices()) {
    for (V adjacentVertex : vertex.getAdjacentVertices()) {
