public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
	// Create a new bipartite graph with the same number of partitions
	// as the number of vertices in the result map
	BipartiteGraph<V,E> bipartite = new BipartiteGraph<V,E>(resultMap.size());

	// Iterate over the vertices in the result map
	for (String vertexId : resultMap.keySet()) {
		// Add a new vertex to the bipartite graph
		V vertex = bipartite.addVertex(vertexId);

		// Find the last underscore in the vertex ID
		int index = vertexId.lastIndexOf('_');

		// If the vertex ID contains an underscore, add an edge from the vertex to
		// the corresponding vertex in the other partition
		if (index != -1) {
			// Get the ID of the corresponding vertex in the other partition
			String otherId = vertexId.substring(0, index);

			// Check if the other vertex is in the result map
			if (resultMap.containsKey(otherId)) {
				E edge = bipartite.addEdge(vertex, otherId);
			}
		}
	}

	// Copy the vertices and edges from the bipartite graph to the target graph
	target.addAllVertices(bipartite.getVertices());
	target.addAllEdges(bipartite.getEdges());
}

