public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {

	// Generate two sets of vertices, one for left and one for right
	Set<V> leftSet = new HashSet<>();
	Set<V> rightSet = new HashSet<>();

	// Initialize a random seed
	Random random = new Random();

	// Generate a random number of vertices for each set
	int leftSize = random.nextInt(target.getVertexCount());
	int rightSize = target.getVertexCount() - leftSize;

	// Add vertices to the sets
	for (int i = 0; i < leftSize; i++) {
		V leftVertex = target.addVertex();
		leftSet.add(leftVertex);
	}
	for (int i = 0; i < rightSize; i++) {
		V rightVertex = target.addVertex();
		rightSet.add(rightVertex);
	}

	// Generate edges between vertices in different sets
	for (V leftVertex : leftSet) {
		for (V rightVertex : rightSet) {
			target.addEdge(leftVertex, rightVertex);
		}
	}

	// Store the vertices in the result map
	resultMap.put("left", leftSet);
	resultMap.put("right", rightSet);
}

