/**
 * Generates a complete bipartite graph with the specified number of nodes in each partition.
 * 
 * @param target       the target graph to add the nodes and edges to
 * @param resultMap    a map to store the node objects in the target graph
 * @param numLeft      the number of nodes in the left partition
 * @param numRight     the number of nodes in the right partition
 * 
 * @throws IllegalArgumentException if numLeft or numRight is less than or equal to 0
 */
public static <V, E> void generateCompleteBipartiteGraph(Graph<V, E> target, Map<String,V> resultMap, int numLeft, int numRight) {
    if (numLeft <= 0 || numRight <= 0) {
        throw new IllegalArgumentException("Number of nodes in each partition must be positive");
    }

    // Create nodes for the left partition
    Set<V> leftPartition = new HashSet<>();
    for (int i = 1; i <= numLeft; i++) {
        V node = resultMap.get("Left" + i);
        if (node == null) {
            node = target.addVertex();
            resultMap.put("Left" + i, node);
        }
        leftPartition.add(node);
    }

    // Create nodes for the right partition
    Set<V> rightPartition = new HashSet<>();
    for (int i = 1; i <= numRight; i++) {
        V node = resultMap.get("Right" + i);
        if (node == null) {
            node = target.addVertex();
            resultMap.put("Right" + i, node);
        }
        rightPartition.add(node);
    }

    // Create edges between nodes in the left and right partitions
    for (V leftNode : leftPartition) {
        for (V rightNode : rightPartition) {
            target.addEdge(leftNode, rightNode, EdgeType.DIRECTED);
        }
    }
}

