/**
   * Returns a prime number which is >= desiredCapacity and very close to desiredCapacity (within 11% if desiredCapacity >= 1000)
   * 
   * @param  desiredCapacity the capacity desired by the user
   * @return                the capacity which should be used for a hashtable
   */
  public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 0) {
      throw new IllegalArgumentException("Desired capacity must be non-negative");
    }

    if (desiredCapacity < 1000) {
      return findPrime(desiredCapacity);
    }
    else {
      int prime = findPrime(desiredCapacity);
      int closestPrime = findClosestPrime(prime, desiredCapacity);
      return closestPrime;
    }
  }

  private static int findPrime(int capacity){
    int current = capacity;
    while (current >= 2) {
      if (isPrime(current)) {
        return current;
      }
      current--;
    }
    // should never reach here, but just in case
    throw new IllegalStateException("Failed to find prime number");
  }

  private static int findClosestPrime(int prime, int desiredCapacity){
    int closest = prime;
    int diff = Integer.MAX_VALUE;
    while (closest >= 2) {
      int diff1 = Math.abs(closest - desiredCapacity);
      if (diff1 < diff) {
        diff = diff1;
        prime = closest;
      }
      closest--;
    }
    return prime;
  }

  private static boolean isPrime(int n){
    for (int i = 2; i < n; i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
  }

public static int nextPrime(int desiredCapacity) {
    // Edge case: If desired capacity is less than 2, return 2
    if (desiredCapacity < 2) {
        return 2;
    }

    // Start with the next prime number after the desired capacity
    int prime = desiredCapacity + 1;

    // Keep incrementing the prime number until we find one that is a prime
    while (!isPrime(prime)) {
        prime += 2;
    }

    return prime;
}

// Helper method to check if a given number is prime
private static boolean isPrime(int num) {
    // Check if the number is divisible by 2 to √n
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 1)
    throw new IllegalArgumentException("Desired capacity must be greater than or equal to 1");

  int prime = desiredCapacity;
  while (!isPrime(prime))
    prime++;

  return prime;
}

private static boolean isPrime(int number) {
  if (number < 2 || number % 3 == 0)
    return false;
  for (int i = 5; i * i <= number; i += 6)
    if (number % i == 0 || number % (i + 2) == 0)
      return false;
  return true;
}

public static int nextPrime(int desiredCapacity) {

boolean isPrime = false;
while (!isPrime) {
for (int divisor = 2; divisor <= Math.sqrt(desiredCapacity); divisor++) {
if (desiredCapacity % divisor == 0) {
desiredCapacity++;
}
}
isPrime = true;
for (int divisor = 2; divisor <= Math.sqrt(desiredCapacity); divisor++) {
if (desiredCapacity % divisor == 0) {
isPrime = false;
break;
}
}
}
return desiredCapacity;
}

