public static String trimTrailingWhitespace(String str) {
    if (str == null) return null;
    int len = str.length();
    int st = 0;
    while ((st < len) && Character.isWhitespace(str.charAt(len))) len--;
    return (st > 0) ? str.substring(0, len) : str;
}

public static String trimTrailingWhitespace(String str) {
    if (str == null) {
      throw new NullPointerException("Input string cannot be null");
    }
    int len = str.length();
    if (len == 0) {
      return str;
    }
    int st = len - 1;
    while (st >= 0 && Character.isWhitespace(str.charAt(st))) {
      st--;
    }
    return str.substring(0, st + 1);
  }
}

