// Find the unused nodes
void findUnusedNodes(Node node, ArrayList<Node> unusedNodes) {

  // Check if the node is unused
  if (node.isUnused()) {
    unusedNodes.add(node);
  }

  // Traverse to the children recursively
  for (Node child : node.getChildren()) {
    findUnusedNodes(child, unusedNodes);
  }
}

// Remove the unused node
void removeNode(Node node) {
  // Check if the node has children
  if (node.isLeaf()) {
    // Remove the node from its parent
    if (node.getParent() != null) {
      node.getParent().removeChild(node);
    }
  } else {
    // Remove the node and its children recursively
    for (Node child : node.getChildren()) {
      removeNode(child);
    }
  }
}

