        throw new IndexOutOfBoundsException("from index " + from + " is out of bounds");
    }
    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("to index " + to + " is out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("from cannot be greater than to");
    }

