private List<Pair<Integer, Integer>> computeMinimalSeparator(E edge) {
    List<Pair<Integer, Integer>> separator = new ArrayList<>();
    for (Edge incidentEdge : graph.getIncidentEdges(edge.getV1())) {
        if (incidentEdge.getV2().equals(edge.getV1())) {
            continue;
