        separator.add(new Pair<>(incidentEdge.getV1().getIndex(), incidentEdge.getV2().getIndex()));
    }
    for (Edge incidentEdge : graph.getIncidentEdges(edge.getV2())) {
        if (incidentEdge.getV2().equals(edge.getV2()) || separator.contains(new Pair<>(incidentEdge.getV1().getIndex(), incidentEdge.getV2().getIndex()))) {
            continue;
        }
        separator.add(new Pair<>(incidentEdge.getV1().getIndex(), incidentEdge.getV2().getIndex()));
    }
    return separator;
