  /**
   * Computes the list of minimal separators for the given edge in the inspected graph
   *
   * @param edge - the edge to compute the list of minimal separators for
   * @return the list of minimal separators for the edge
   */
  private List<Pair<Integer, Integer>> computeSeparatorsForEdge(E edge) {
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

    // Iterate over all vertices in the graph
    for (V vertex : graph.getVertices()) {
      // Check if the vertex is adjacent to the edge
      if (graph.edgeExists(vertex, edge.getTail()) || graph.edgeExists(vertex, edge.getHead())) {
        // Compute the separator for the edge and the vertex
        Pair<Integer, Integer> separator = computeSeparator(edge, vertex);

        // Add the separator to the list of minimal separators if it is not already in the list
        if (!minimalSeparators.contains(separator)) {
          minimalSeparators.add(separator);
        }
      }
    }

    return minimalSeparators;
  }

  /**
   * Computes the separator between two vertices in the given edge
   *
   * @param edge - the edge that connects the two vertices
   * @param vertex - the vertex to compute the separator for
   * @return the separator between the edge and the vertex
   */
  private Pair<Integer, Integer> computeSeparator(E edge, V vertex) {
    // Compute the neighbors of the vertex in the edge
    List<V> neighbors = graph.getNeighbors(vertex, edge);

    // Compute the intersection of the neighbors of the vertex with the edge
    List<V> intersection = new ArrayList<>();
    for (V neighbor : neighbors) {
      if (edge.contains(neighbor)) {
        intersection.add(neighbor);
      }
    }

    // Compute the separator by finding the extremal vertices in the intersection
    V headVertex = intersection.get(0);
    V tailVertex = intersection.get(1);

    // Check if the head vertex is lexicographically smaller than the tail vertex
    if (headVertex.compareTo(tailVertex) > 0) {
      // If it is not, then swap the head and tail vertices
      V temp = headVertex;
      headVertex = tailVertex;
      tailVertex = temp;
    }

    // Return the separator as a pair of the head and tail vertices
    return new Pair<>(headVertex, tailVertex);
  }

