private List<Pair<Integer, Integer>> computeMinimalSeparators(E edge) {
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
    for (V vertex : graph.getVertices()) {
        if (vertex != edge.getSource() && vertex != edge.getTarget()) {
            List<Pair<V, E>> separators = graph.getSeparators(vertex, edge);
            minimalSeparators.addAll(separators.stream().map(separator -> new Pair<>(separator.getKey(), separator.getValue())).collect(Collectors.toList()));
        }
    }
    return minimalSeparators;
}

