private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is empty
    if (vertices.isEmpty()) {
        return false;
    }

    // Create a map to keep track of the degree of each vertex in the graph
    Map<V, Integer> degreeMap = new HashMap<>();
    for (V vertex : vertices) {
        degreeMap.put(vertex, graph.degree(vertex));
    }

    // Check if all vertices in the graph have the same degree
    int expectedDegree = degreeMap.get(vertices.iterator().next());
    for (V vertex : vertices) {
        if (degreeMap.get(vertex) != expectedDegree) {
            return false;
        }
    }

    // Check if all edges connect two vertices in the subgraph
    for (E edge : graph.edges()) {
        V u = graph.incidentVertex(edge, true);
        V v = graph.incidentVertex(edge, false);
        if (!vertices.contains(u) || !vertices.contains(v)) {
            return false;
        }
    }

    // If the graph is a clique, then it has no isolated vertices
    if (vertices.size() == graph.vertexCount() && degreeMap.values().stream().allMatch(d -> d == expectedDegree)) {
        return true;
    }

    return false;
}
