public static List<Integer> computeUpperBounds(List<K> keys) {
    // Use a priority queue to maintain a sorted list of
    // the keys, with the largest key at the top of the queue.
    // The key of the top of the queue is the minimum upper bound.
    PriorityQueue<K> pq = new PriorityQueue<>((a, b) -> b.compareTo(a));

    // Add each key to the priority queue
    for (K key : keys) {
        pq.add(key);
    }

    // Initialize the list of upper bounds with the first key
    List<Integer> upperBounds = new ArrayList<>();
    upperBounds.add(pq.peek());

    // Loop through the remaining keys
    while (!pq.isEmpty()) {
        // Get the next key and the current upper bound
        K key = pq.poll();
        int currentUpperBound = upperBounds.get(upperBounds.size() - 1);

        // If the key is less than the current upper bound,
        // add the key to the list of upper bounds
        if (key.compareTo(currentUpperBound) <= 0) {
            upperBounds.add(key);
        }
    }

    return upperBounds;
}

