public int readTag() throws IOException {
    int b;
    try {
        b = this.readUnsignedByte(); // Read the first byte of the tag
    } catch (EOFException e) {
        return 0; // If an EOF is reached, return 0
    }
    int tag = b & 0x7F; // If not at the end, mask off the high bit to get the tag number
    if ((b & 0x80) != 0) { // If the high bit is set, this is the first byte of a multi-byte tag
        int i;
        for (i = 1; i < 4; i++) { // Read up to 3 more bytes of the tag
            try {
                tag |= (this.readUnsignedByte() & 0x7F) << (7 * i);
            } catch (EOFException e) {
                break;
            }
        }
        if (i < 4) { // If the last byte was not part of the tag, return EOF
            return 0;
        }
    }
    return tag;
}

