public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: file or timeRanges is null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            List<String> parts = parseLine(line);
            if (parts.size() < 7) {
                throw new IllegalArgumentException("Invalid file format: not enough parts in line");
            }

            String startTime = parts.get(0);
            String endTime = parts.get(1);
            String cpuUsage = parts.get(2);
            String memUsage = parts.get(3);
            String threadId = parts.get(4);
            String threadName = parts.get(5);
            String threadState = parts.get(6);

            if (!isInTimeRanges(timeRanges, startTime)) {
                continue;
            }

            ThreadSnapshot threadSnapshot = new ThreadSnapshot(startTime, endTime, cpuUsage, memUsage, threadId, threadName, threadState);
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IOException e) {
        throw new IOException("Error reading file: " + e.getMessage(), e);
    }

    return threadSnapshots;
}

private static List<String> parseLine(String line) {
    List<String> parts = new ArrayList<>();
